import { useState, useMemo } from 'react'
import UnitInput from '../../components/shared/UnitInput'
import ResultBox from '../../components/shared/ResultBox'
import { calcColumnReinf } from '../../engines/columnReinf'

const REBAR_METRIC   = [
  { name: 'D10', area_mm2: 71.3 }, { name: 'D13', area_mm2: 126.7 },
  { name: 'D16', area_mm2: 198.6 }, { name: 'D19', area_mm2: 284.9 },
  { name: 'D22', area_mm2: 387.1 }, { name: 'D25', area_mm2: 506.7 },
]
const REBAR_IMPERIAL = [
  { name: '#3', area_in2: 0.11 }, { name: '#4', area_in2: 0.20 },
  { name: '#5', area_in2: 0.31 }, { name: '#6', area_in2: 0.44 },
  { name: '#7', area_in2: 0.60 }, { name: '#8', area_in2: 0.79 },
]
const MM_TO_IN = 0.03937

export default function ColumnView() {
  const [B,      setB]      = useState('500')
  const [H,      setH]      = useState('500')
  const [rhoStr, setRhoStr] = useState('1.0')   // % string

  const rho_g = Math.min(Math.max(parseFloat(rhoStr) || 1.0, 0.5), 8.0) / 100

  const result = useMemo(() =>
    calcColumnReinf({
      B_mm: parseFloat(B) || 0,
      H_mm: parseFloat(H) || 0,
      rho_g,
      rebarMetric: REBAR_METRIC,
      rebarImperial: REBAR_IMPERIAL,
    }), [B, H, rho_g]
  )

  return (
    <div>
      <h3 style={titleStyle}>COLUMN — Min. Longitudinal Reinforcement</h3>
      <p style={descStyle}>KDS 14 20 50 / ACI 318-19 §10.6.1.1 — 0.01·Ag ≤ Ast ≤ 0.08·Ag</p>

      {/* ρg input — shared across both codes */}
      <div style={{
        marginBottom: 20, padding: '12px 16px', borderRadius: 8,
        background: 'var(--bg-inset)', border: '1px solid var(--bd-subtle)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>
          <div style={{ fontWeight: 700, fontSize: 13, color: 'var(--ac-main)', whiteSpace: 'nowrap' }}>
            Design Steel Ratio ρg
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, flex: 1 }}>
            <input
              type="range" min="0.5" max="8.0" step="0.5"
              value={parseFloat(rhoStr) || 1.0}
              onChange={e => setRhoStr(e.target.value)}
              style={{ flex: 1, accentColor: 'var(--ac-main)' }}
            />
            <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
              <input
                type="number" min="0.5" max="8.0" step="0.5"
                value={rhoStr}
                onChange={e => setRhoStr(e.target.value)}
                style={{
                  width: 64, background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)',
                  borderRadius: 5, padding: '4px 6px', color: 'var(--tx-primary)',
                  fontSize: 14, fontWeight: 700, textAlign: 'center',
                }}
              />
              <span style={{ fontSize: 13, color: 'var(--tx-secondary)' }}>%</span>
            </div>
          </div>
          <div style={{ fontSize: 11, color: 'var(--tx-muted)', whiteSpace: 'nowrap' }}>
            Range: 0.5% ~ 8.0% | Default: 1.0%
          </div>
        </div>
        {/* Quick presets */}
        <div style={{ display: 'flex', gap: 6, marginTop: 10 }}>
          {['0.5', '1.0', '1.5', '2.0', '3.0', '4.0', '6.0', '8.0'].map(v => (
            <button key={v} onClick={() => setRhoStr(v)} style={{
              padding: '3px 10px', borderRadius: 4, fontSize: 11, cursor: 'pointer',
              border: '1px solid var(--bd-subtle)',
              background: rhoStr === v ? 'var(--ac-main)' : 'var(--bg-card)',
              color: rhoStr === v ? '#000' : 'var(--tx-secondary)',
            }}>{v}%</button>
          ))}
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* KS */}
        <div style={cardKS}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--ac-main)' }}>🇰🇷 KS CODE (METRIC)</h4>
          <UnitInput id="col-B" label="Section Width B"  unit="mm" value={B} onChange={setB} />
          <UnitInput id="col-H" label="Section Height H" unit="mm" value={H} onChange={setH} />
          {result && (
            <ResultBox title={`Min. Steel Area (ρg = ${(rho_g * 100).toFixed(1)}%)`} accent>
              <p style={rowStyle}>Ag = <Val>{result.metric.Ag.toFixed(0)} mm²</Val></p>
              <p style={rowStyle}>As,req = <Val>{result.metric.As_req.toFixed(0)} mm²</Val>
                <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginLeft: 8 }}>
                  (ρg = {(rho_g * 100).toFixed(1)}%)
                </span>
              </p>
              <p style={{ ...rowStyle, fontSize: 11, color: 'var(--tx-muted)' }}>
                As,min (1%) = {result.metric.As_min.toFixed(0)} mm² &nbsp;|&nbsp;
                As,max (8%) = {result.metric.As_max.toFixed(0)} mm²
              </p>
              <SubLabel>D-Bar Count</SubLabel>
              <RebarList items={result.metric.rebars} />
            </ResultBox>
          )}
        </div>

        {/* ACI */}
        <div style={cardACI}>
          <h4 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, color: 'var(--tx-primary)' }}>🇺🇸 ACI CODE (IMPERIAL)</h4>
          <UnitInput id="col-Bin" label="Width B" unit="in"
            value={B ? (parseFloat(B) * MM_TO_IN).toFixed(2) : ''}
            onChange={v => setB((parseFloat(v) / MM_TO_IN).toFixed(1))} />
          <UnitInput id="col-Hin" label="Height H" unit="in"
            value={H ? (parseFloat(H) * MM_TO_IN).toFixed(2) : ''}
            onChange={v => setH((parseFloat(v) / MM_TO_IN).toFixed(1))} />
          {result && (
            <ResultBox title={`Required Steel Area (ρg = ${(rho_g * 100).toFixed(1)}%)`}>
              <p style={rowStyle}>Ag = <Val>{result.imperial.Ag.toFixed(2)} in²</Val></p>
              <p style={rowStyle}>As,req = <Val>{result.imperial.As_req.toFixed(3)} in²</Val></p>
              <p style={{ ...rowStyle, fontSize: 11, color: 'var(--tx-muted)' }}>
                As,min (1%) = {result.imperial.As_min.toFixed(3)} in² &nbsp;|&nbsp;
                As,max (8%) = {result.imperial.As_max.toFixed(3)} in²
              </p>
              <SubLabel>#-Bar Count</SubLabel>
              <RebarList items={result.imperial.rebars} />
            </ResultBox>
          )}
        </div>
      </div>
    </div>
  )
}

function Val({ children }) {
  return <span style={{ fontWeight: 700, color: 'var(--val-pos)' }}>{children}</span>
}
function SubLabel({ children }) {
  return <h5 style={{ fontSize: 11, fontWeight: 600, color: 'var(--tx-secondary)', marginTop: 12, marginBottom: 6, paddingTop: 10, borderTop: '1px solid var(--bd-subtle)' }}>{children}</h5>
}
function RebarList({ items }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      {items.map(b => (
        <div key={b.name} style={{
          background: 'var(--bg-inset)', borderRadius: 6, padding: '6px 12px',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        }}>
          <span style={{ color: 'var(--tx-secondary)', fontSize: 12, fontWeight: 600 }}>{b.name}</span>
          <span style={{ fontWeight: 700, color: b.exceedsMax ? 'var(--val-warn)' : 'var(--val-pos)', fontSize: 13 }}>
            {b.count}-{b.name}{b.exceedsMax ? ' ⚠ exceeds ρmax' : ''}
          </span>
        </div>
      ))}
    </div>
  )
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const rowStyle   = { fontSize: 15, color: 'var(--tx-primary)', marginBottom: 4 }
const cardBase = { background: 'var(--bg-card)', border: '1px solid', borderRadius: 10, padding: 20 }
const cardKS   = { ...cardBase, borderColor: 'var(--bd-accent)' }
const cardACI  = { ...cardBase, borderColor: 'var(--bd-muted)' }
