/**
 * Column Min. Longitudinal Reinforcement
 * KDS 14 20 50 / ACI 318-19 §10.6.1.1
 * 0.01·Ag ≤ Ast ≤ 0.08·Ag  (default ρg = 0.01)
 */

const MM_TO_IN = 0.03937;

/**
 * @param {object} p
 * @param {number} p.B_mm
 * @param {number} p.H_mm
 * @param {number} [p.rho_g=0.01]   design steel ratio (0.005 ~ 0.08)
 * @param {Array}  p.rebarMetric
 * @param {Array}  p.rebarImperial
 */
export function calcColumnReinf({ B_mm, H_mm, rho_g = 0.01, rebarMetric, rebarImperial }) {
  if (B_mm <= 0 || H_mm <= 0) return null;
  const rho = Math.min(Math.max(rho_g, 0.005), 0.08);  // clamp to valid range

  const Ag_mm2   = B_mm * H_mm;
  const As_mm2   = rho * Ag_mm2;
  const As_min_mm2 = 0.01 * Ag_mm2;
  const As_max_mm2 = 0.08 * Ag_mm2;

  const B_in  = B_mm * MM_TO_IN;
  const H_in  = H_mm * MM_TO_IN;
  const Ag_in2  = B_in * H_in;
  const As_in2  = rho * Ag_in2;
  const As_min_in2 = 0.01 * Ag_in2;
  const As_max_in2 = 0.08 * Ag_in2;

  return {
    rho,
    metric: {
      Ag: Ag_mm2,
      As_req: As_mm2,
      As_min: As_min_mm2,
      As_max: As_max_mm2,
      rebars: rebarMetric.map(bar => {
        const count = Math.ceil(As_mm2 / bar.area_mm2);
        const rhoActual = (count * bar.area_mm2) / Ag_mm2;
        return { name: bar.name, count, rho: rhoActual, exceedsMax: rhoActual > 0.08 };
      }),
    },
    imperial: {
      Ag: Ag_in2,
      As_req: As_in2,
      As_min: As_min_in2,
      As_max: As_max_in2,
      rebars: rebarImperial.map(bar => {
        const count = Math.ceil(As_in2 / bar.area_in2);
        const rhoActual = (count * bar.area_in2) / Ag_in2;
        return { name: bar.name, count, rho: rhoActual, exceedsMax: rhoActual > 0.08 };
      }),
    },
  };
}
